import six
import struct
from google.protobuf.internal import encoder

from . import ProtobufTypeId


class ProtobufEncoder(object):

    def __init__(self, definition):
        self.definition = definition
        self.protobuf_msg = []
        self.value_encoders = {
            bytes: self._encode_bytes,
            str: self._encode_string,
            int: self._encode_integer,
            float: self._encode_float,
            six.integer_types[-1]: self._encode_integer,
        }

    def encode(self, object_dump):
        """Encode managed object dump."""
        for name, value in six.iteritems(object_dump):
            param = self.definition[name]
            if param.is_array():
                self._encode_array(param, value)
            else:
                self._encode_param(param, value)
        return six.b('').join(self.protobuf_msg)

    def _encode_array(self, param, value_list):
        for value in value_list:
            self._encode_param(param, value)

    def _encode_param(self, param, value):
        converted_value = self._convert_param_value(param, value)
        self.value_encoders[type(converted_value)](param.id, converted_value)

    def _convert_param_value(self, param, value):
        if param.is_enum():
            return self._convert_enum_type(param.get_type_definition(), value)
        elif param.is_complex():
            return self._convert_complex_type(param.get_type_definition(), value)
        else:
            return self._convert_simple_type(param, value)

    @staticmethod
    def _encode_zig_zag(value):
        return (int(value) << 1) ^ (int(value) >> 31)

    def _convert_simple_type(self, param, value):
        modified = param.value_modifier.revert(value)
        if "sint32" in str(param.protobuf_type):
            modified = self._encode_zig_zag(modified)
        if "int32" in str(param.protobuf_type):
            return int(modified)
        else:
            return param.get_protobuf_type()(modified)

    def _convert_enum_type(self, definition, value):
        if isinstance(value, (six.string_types, six.binary_type)) and value in definition.enum:
            return definition.enum[value]
        return value

    def _convert_complex_type(self, definition, value):
        return ProtobufEncoder(definition).encode(value)

    def _encode_string(self, param_id, value):
        if six.PY3 and isinstance(value, str):
            value = value.encode('utf-8')
        self._encode_bytes(param_id, value)

    def _encode_bytes(self, param_id, value):
        self._encode_tag(param_id, ProtobufTypeId.LENGTH_DELIMITED)
        self._encode_varint(len(value))
        self._encode(value)

    def _encode_float(self, param_id, value):
        self._encode_tag(param_id, ProtobufTypeId.FIXED_64)
        self._encode(struct.pack('<d', value))

    def _encode_integer(self, param_id, value):
        self._encode_tag(param_id, ProtobufTypeId.VARINT)
        self._encode_varint(value)

    def _encode_tag(self, param_id, protobuf_type_id):
        tag = (param_id << 3) | protobuf_type_id
        self._encode_varint(tag)

    def _encode_varint(self, value):
        try:
            encoder._EncodeSignedVarint(self._encode, value)  # pylint: disable-msg=E1120
        except TypeError:
            encoder._EncodeSignedVarint(self._encode, value, unused_deterministic=True)  # pylint: disable=unexpected-keyword-arg

    def _encode(self, bytes):
        self.protobuf_msg.append(bytes)
